// PalDex: send push notifications. A Supabase Edge Function (Deno), called only by pg_cron (see
// supabase/migrations/20261123000000_push.sql) with the header `x-cron-key`:
//   {"mode":"drain"}  every minute while the outbox has unsent rows: send them with Web Push
//   {"mode":"meds"}   every hour at :05: queue today's medicine reminders for people whose medicine hour it is
// Secrets (Edge Functions → Secrets; never in the repo): PUSH_CRON_KEY, VAPID_PUBLIC_KEY, VAPID_PRIVATE_KEY,
// VAPID_SUBJECT (a mailto: address). SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are provided by Supabase.
// Deploy with JWT verification off (the cron sends its own key, not a sign-in):
//   supabase functions deploy send-push --no-verify-jwt
// The logic lives in core.ts (tested with Vitest); this file only connects it to the database and the network.
import webpush from 'npm:web-push@3.6.7';
import { createClient } from 'npm:@supabase/supabase-js@2.119.0';

const env = (k: string) => Deno.env.get(k) ?? '';
const sb = createClient(env('SUPABASE_URL'), env('SUPABASE_SERVICE_ROLE_KEY'), { auth: { persistSession: false } });

function check<T>(r: { data: T; error: { message: string } | null }): T {
  if (r.error) throw new Error(r.error.message);
  return r.data;
}
/** The rows of a list query (never null). */
const rows = <T>(r: { data: T[] | null; error: { message: string } | null }): T[] => check(r) ?? [];

/** All rows of a query, 1000 at a time (PostgREST's page limit). */
async function all<T>(page: (from: number, to: number) => PromiseLike<{ data: T[] | null; error: { message: string } | null }>): Promise<T[]> {
  const out: T[] = [];
  for (let from = 0; ; from += 1000) {
    const got = check(await page(from, from + 999)) ?? [];
    out.push(...got); if (got.length < 1000) return out;
  }
}

const vapid = () => ({ subject: env('VAPID_SUBJECT'), publicKey: env('VAPID_PUBLIC_KEY'), privateKey: env('VAPID_PRIVATE_KEY') });

async function send(s: Subscription, payload: unknown, topic: string | undefined): Promise<number> {
  // web-push builds the encrypted request (VAPID JWT + aes128gcm); fetch sends it (no Node https needed on Deno)
  const r = webpush.generateRequestDetails({ endpoint: s.endpoint, keys: { p256dh: s.p256dh, auth: s.auth } }, JSON.stringify(payload),
    { vapidDetails: vapid(), TTL: TTL_SECONDS, ...(topic ? { topic } : {}), urgency: 'normal' });
  const res = await fetch(r.endpoint, { method: r.method, headers: r.headers as Record<string, string>, body: r.body, signal: AbortSignal.timeout(10_000) });
  await res.body?.cancel();
  return res.status;
}

const runDrain = () => {
  // without the VAPID secrets nothing can be sent: fail before touching the outbox, so no row loses a try
  const v = vapid();
  if (!v.subject || !v.publicKey || !v.privateKey) throw new Error('not set up (VAPID_PUBLIC_KEY, VAPID_PRIVATE_KEY, VAPID_SUBJECT)');
  return drainNow();
};
const drainNow = () => drain({
  unsent: async (limit) => rows(await sb.from('push_outbox').select('id, user_id, kind, title, body, url, tag, tries')
    .is('sent_at', null).lt('tries', MAX_TRIES).order('created_at').limit(limit)) as OutboxRow[],
  // one conditional update per tries value: a row another run already claimed no longer matches
  claim: async (want) => {
    const got: number[] = [];
    for (const t of new Set(want.map((r) => r.tries))) {
      const ids = want.filter((r) => r.tries === t).map((r) => r.id);
      const done = rows(await sb.from('push_outbox').update({ tries: t + 1 }).in('id', ids).eq('tries', t).is('sent_at', null).select('id')) as { id: number }[];
      got.push(...done.map((r) => r.id));
    }
    return got;
  },
  subscriptions: async (ids) => rows(await sb.from('push_subscriptions').select('endpoint, user_id, p256dh, auth').in('user_id', ids)) as Subscription[],
  send,
  markSent: async (ids) => { check(await sb.from('push_outbox').update({ sent_at: new Date().toISOString() }).in('id', ids)); },
  giveUp: async (ids) => { check(await sb.from('push_outbox').update({ tries: MAX_TRIES }).in('id', ids)); },
  deleteSubscriptions: async (eps) => { check(await sb.from('push_subscriptions').delete().in('endpoint', eps)); },
  log: (m) => console.log(m),
});

const runMeds = () => queueMeds({
  people: async () => {
    const subs = rows(await sb.from('push_subscriptions').select('user_id')) as { user_id: string }[];
    const ids = [...new Set(subs.map((s) => s.user_id))];
    if (!ids.length) return [];
    const prefs = rows(await sb.from('push_prefs').select('user_id, tz, meds, med_hour').in('user_id', ids)) as Prefs[];
    const by = new Map(prefs.map((p) => [p.user_id, p]));
    return ids.map((user_id) => ({ user_id, prefs: by.get(user_id) }));
  },
  petsOf: async (ids) => {
    // households (and pets from before households, still shared per pet)
    const hm = rows(await sb.from('household_members').select('household_id, user_id').in('user_id', ids)) as { household_id: string; user_id: string }[];
    const cm = rows(await sb.from('cat_members').select('cat_id, user_id').in('user_id', ids)) as { cat_id: string; user_id: string }[];
    const hids = [...new Set(hm.map((m) => m.household_id))];
    const cats = [
      ...(hids.length ? rows(await sb.from('cats').select('id, household_id, data').in('household_id', hids)) : []),
      ...(cm.length ? rows(await sb.from('cats').select('id, household_id, data').in('id', [...new Set(cm.map((m) => m.cat_id))]).is('household_id', null)) : []),
    ] as { id: string; household_id: string | null; data: { name?: string } }[];
    const catIds = [...new Set(cats.map((c) => c.id))];
    // every medicine entry (not just recent ones): a yearly vaccine's next-due date comes from last year's entry
    const meds = catIds.length ? await all((a, b) => sb.from('care').select('cat_id, kind, at, deleted, data').eq('kind', 'med').in('cat_id', catIds).order('id').range(a, b)) as (MedEntry & { cat_id: string })[] : [];
    const itemsOf = new Map<string, MedEntry[]>();
    for (const m of meds) itemsOf.set(m.cat_id, [...(itemsOf.get(m.cat_id) ?? []), { ...m, at: Number(m.at) }]);
    const pet = (c: (typeof cats)[number]): PetMeds => ({ catId: c.id, name: c.data?.name?.trim() || 'Your cat', items: itemsOf.get(c.id) ?? [] });
    const out = new Map<string, PetMeds[]>();
    for (const id of ids) {
      const mine = new Set([...hm.filter((m) => m.user_id === id).map((m) => m.household_id)]);
      const direct = new Set(cm.filter((m) => m.user_id === id).map((m) => m.cat_id));
      const seen = new Set<string>();
      out.set(id, cats.filter((c) => (c.household_id ? mine.has(c.household_id) : direct.has(c.id)) && !seen.has(c.id) && seen.add(c.id)).map(pet));
    }
    return out;
  },
  recent: async (ids) => {
    const since = new Date(Date.now() - 864e5).toISOString();
    const queued = rows(await sb.from('push_outbox').select('user_id, tag').in('user_id', ids).gt('created_at', since)) as { user_id: string; tag: string }[];
    const out = new Map<string, { tags: Set<string>; count: number }>();
    for (const r of queued) { const x = out.get(r.user_id) ?? { tags: new Set<string>(), count: 0 }; x.tags.add(r.tag); x.count++; out.set(r.user_id, x); }
    return out;
  },
  enqueue: async (add) => { check(await sb.from('push_outbox').insert(add)); },
});

Deno.serve(async (req) => {
  try {
    return await handle(req, { cronKey: Deno.env.get('PUSH_CRON_KEY'), drain: runDrain, meds: () => runMeds() });
  } catch (e) {
    console.error(e);
    return new Response(JSON.stringify({ error: (e as Error).message }), { status: 500, headers: { 'Content-Type': 'application/json' } });
  }
});

// ---- core.ts ----
/* The send-push Edge Function's logic, with the database and the network passed in, so Vitest can run it without
   Deno, Supabase or a real push service (see core.test.ts). `index.ts` wires it to supabase-js and web-push.
   Plan: docs/plans/2026-11-23-push-notifications.md. */

export type Kind = 'friends' | 'treats' | 'photos' | 'meds';
/** A row of public.push_outbox. */
export interface OutboxRow { id: number; user_id: string; kind: Kind; title: string; body: string; url: string; tag: string; tries: number }
/** A row of public.push_subscriptions (one phone or browser). */
export interface Subscription { endpoint: string; user_id: string; p256dh: string; auth: string }
/** What the service worker gets (`public/push-sw.js`); Web Push encrypts it end to end. */
export interface Payload { title: string; body: string; url: string; tag: string }

export const MAX_TRIES = 3;
export const BATCH = 200;
export const TTL_SECONDS = 12 * 60 * 60;
export const DAILY_CAP = 20;

export const payloadFor = (r: Pick<OutboxRow, 'title' | 'body' | 'url' | 'tag'>): Payload => ({ title: r.title, body: r.body, url: r.url, tag: r.tag });

/** Web Push `Topic` header for a tag: at most 32 URL-safe characters (RFC 8030 §5.4), so a hash of it. A newer push
    with the same topic replaces one the phone hasn't fetched yet. Empty tag: no topic. */
export async function topicFor(tag: string): Promise<string | undefined> {
  if (!tag) return undefined;
  const h = new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(tag)));
  let s = ''; for (const b of h) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '').slice(0, 32);
}

/** What happened when sending to one subscription. */
export type SendOutcome = 'sent' | 'gone' | 'retry' | 'failed';
/** Push service status → outcome: 2xx delivered; 404/410 the phone dropped it (delete it); 408/429/5xx try again
    later; any other 4xx (bad key, too big) won't get better by retrying. */
export function outcomeOf(status: number): SendOutcome {
  if (status >= 200 && status < 300) return 'sent';
  if (status === 404 || status === 410) return 'gone';
  if (status === 408 || status === 429 || status >= 500) return 'retry';
  return 'failed';
}

export interface DrainDeps {
  /** Unsent rows with tries < MAX_TRIES, oldest first. */
  unsent(limit: number): Promise<OutboxRow[]>;
  /** Claim rows (tries + 1) only if no one else has: returns the ids this run got. Two overlapping runs can't both
      send the same row. */
  claim(rows: OutboxRow[]): Promise<number[]>;
  subscriptions(userIds: string[]): Promise<Subscription[]>;
  /** Send one encrypted push; resolves to the push service's HTTP status (throws on a network error). */
  send(sub: Subscription, payload: Payload, topic: string | undefined): Promise<number>;
  markSent(ids: number[]): Promise<void>;
  /** Give up on these rows (no phone left, or a permanent error): tries = MAX_TRIES, so the cron stops calling. */
  giveUp(ids: number[]): Promise<void>;
  deleteSubscriptions(endpoints: string[]): Promise<void>;
  log?(msg: string): void;
}

export interface DrainResult { claimed: number; sent: number; retry: number; dropped: number; gone: number }

/** Send what's waiting. Per row: delivered to at least one of the person's phones → sent; else if any phone had a
    passing problem → left for the next run (its tries were already counted by the claim); else (no phones, or all
    gone or refused for good) → given up. */
export async function drain(d: DrainDeps, limit = BATCH, parallel = 8): Promise<DrainResult> {
  const rows = await d.unsent(limit);
  const res: DrainResult = { claimed: 0, sent: 0, retry: 0, dropped: 0, gone: 0 };
  if (!rows.length) return res;
  const mine = new Set(await d.claim(rows));
  const todo = rows.filter((r) => mine.has(r.id));
  res.claimed = todo.length;
  if (!todo.length) return res;

  const subs = await d.subscriptions([...new Set(todo.map((r) => r.user_id))]);
  const byUser = new Map<string, Subscription[]>();
  for (const s of subs) byUser.set(s.user_id, [...(byUser.get(s.user_id) ?? []), s]);

  const gone = new Set<string>(); const sent: number[] = []; const dead: number[] = [];
  const one = async (r: OutboxRow) => {
    const phones = (byUser.get(r.user_id) ?? []).filter((s) => !gone.has(s.endpoint));
    const payload = payloadFor(r); const topic = await topicFor(r.tag);
    const outs = await Promise.all(phones.map(async (s): Promise<SendOutcome> => {
      let o: SendOutcome;
      try { o = outcomeOf(await d.send(s, payload, topic)); } catch (e) { d.log?.(`push ${r.id}: ${(e as Error).message}`); o = 'retry'; }
      if (o === 'gone') gone.add(s.endpoint);
      if (o === 'failed' || o === 'retry') d.log?.(`push ${r.id} → ${new URL(s.endpoint).host}: ${o}`);
      return o;
    }));
    if (outs.includes('sent')) sent.push(r.id);
    else if (outs.includes('retry')) res.retry++; // the claim already counted this try; at MAX_TRIES it stops
    else dead.push(r.id);
  };
  for (let i = 0; i < todo.length; i += parallel) await Promise.all(todo.slice(i, i + parallel).map(one));

  if (sent.length) await d.markSent(sent);
  if (dead.length) await d.giveUp(dead);
  if (gone.size) await d.deleteSubscriptions([...gone]);
  res.sent = sent.length; res.dropped = dead.length; res.gone = gone.size;
  return res;
}

// ---------------------------------------------------------------------------------------------------------------
// medicine reminders: once a day, at each person's medicine hour
// ---------------------------------------------------------------------------------------------------------------

export interface Prefs { user_id: string; tz: string; meds: boolean; med_hour: number }
/** Someone who allowed notifications but whose prefs row is missing gets the table's defaults. */
export const DEFAULT_PREFS: Omit<Prefs, 'user_id'> = { tz: 'America/New_York', meds: true, med_hour: 9 };

/** The hour (0–23) it is now in a time zone; null for a zone this runtime doesn't know. */
export function hourIn(now: number, tz: string): number | null {
  try {
    const h = new Intl.DateTimeFormat('en-US', { timeZone: tz, hour: 'numeric', hourCycle: 'h23' }).format(new Date(now));
    return Number(h) % 24;
  } catch { return null; }
}

export interface PetMeds { catId: string; name: string; items: MedEntry[] }
export interface MedsDeps {
  /** Everyone with at least one phone subscribed, with their prefs (or none yet). */
  people(): Promise<{ user_id: string; prefs?: Prefs }[]>;
  /** The pets each person lives with (their households, plus older per-pet sharing), with their medicine entries. */
  petsOf(userIds: string[]): Promise<Map<string, PetMeds[]>>;
  /** Tags already queued for each person in the last day, and how many they got (for the dedupe and the daily cap). */
  recent(userIds: string[]): Promise<Map<string, { tags: Set<string>; count: number }>>;
  enqueue(rows: Omit<OutboxRow, 'id' | 'tries'>[]): Promise<void>;
}

/** The notification for one pet's medicine due today, or null when nothing is. */
export function medsNotice(pet: string, items: readonly MedEntry[], now: number, tz: string): { title: string; body: string } | null {
  const due = medsDue(items, now, tz);
  if (!due.length) return null;
  if (due.length === 1) return { title: `${pet}: ${due[0].name} due`.slice(0, 80), body: dueLine(due[0]).slice(0, 160) };
  return { title: `${pet}: ${due.length} medicines due`.slice(0, 80), body: due.map((d) => d.name).join(', ').slice(0, 160) };
}

/** Queue today's medicine notifications for everyone whose medicine hour it is now. Run at :05 every hour. */
export async function queueMeds(d: MedsDeps, now = Date.now()): Promise<{ people: number; queued: number }> {
  const due = (await d.people()).map((p) => ({ user_id: p.user_id, ...DEFAULT_PREFS, ...p.prefs }))
    .filter((p) => p.meds && hourIn(now, p.tz) === p.med_hour);
  if (!due.length) return { people: 0, queued: 0 };
  const ids = due.map((p) => p.user_id);
  const [pets, recent] = await Promise.all([d.petsOf(ids), d.recent(ids)]);
  const rows: Omit<OutboxRow, 'id' | 'tries'>[] = [];
  for (const p of due) {
    const r = recent.get(p.user_id) ?? { tags: new Set<string>(), count: 0 };
    for (const pet of pets.get(p.user_id) ?? []) {
      const n = medsNotice(pet.name, pet.items, now, p.tz); if (!n) continue;
      const tag = `meds-${pet.catId}-${dayIn(now, p.tz)}`.slice(0, 100);
      if (r.tags.has(tag) || r.count >= DAILY_CAP) continue;
      r.tags.add(tag); r.count++;
      rows.push({ user_id: p.user_id, kind: 'meds', title: n.title, body: n.body, url: '#/', tag });
    }
  }
  if (rows.length) await d.enqueue(rows);
  return { people: due.length, queued: rows.length };
}

// ---------------------------------------------------------------------------------------------------------------
// the request: only the cron (or the PM testing by hand) with the shared key
// ---------------------------------------------------------------------------------------------------------------

/** Constant-time string compare, so the key can't be guessed a character at a time. */
export function sameKey(a: string, b: string): boolean {
  const x = new TextEncoder().encode(a), y = new TextEncoder().encode(b);
  let diff = x.length ^ y.length;
  for (let i = 0; i < Math.max(x.length, y.length); i++) diff |= (x[i] ?? 0) ^ (y[i] ?? 0);
  return diff === 0;
}

const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } });

export interface HandlerDeps { cronKey: string | undefined; drain(): Promise<DrainResult>; meds(): Promise<{ people: number; queued: number }> }
export async function handle(req: Request, d: HandlerDeps): Promise<Response> {
  if (req.method !== 'POST') return json({ error: 'POST only' }, 405);
  if (!d.cronKey || d.cronKey.length < 16) return json({ error: 'not set up (PUSH_CRON_KEY)' }, 503);
  if (!sameKey(req.headers.get('x-cron-key') ?? '', d.cronKey)) return json({ error: 'forbidden' }, 403);
  let mode: unknown;
  try { mode = ((await req.json()) as { mode?: unknown }).mode; } catch { return json({ error: 'bad body' }, 400); }
  if (mode === 'drain') return json(await d.drain());
  if (mode === 'meds') return json(await d.meds());
  return json({ error: 'mode must be "drain" or "meds"' }, 400);
}

// ---- _shared/meds.ts ----
/* Medicine due today: shared by the app (Home's Medicine card, via `src/engine/care.ts`) and the `send-push` Edge
   Function (the daily medicine notification), so both always agree. Plain TypeScript with no imports, so it runs in
   the browser, in Vitest and in Deno. */

/** The parts of a care entry of kind `med` that this needs (the app's `CareItem<'med'>` fits). */
export interface MedEntry {
  kind: string;
  at: number;
  deleted?: boolean;
  data: { name: string; what: string; nextDue?: string; course?: { times: number; until: string } };
}

export interface MedDue<M extends MedEntry = MedEntry> {
  key: string; name: string; what: M['data']['what']; kind: 'course' | 'due';
  given: number; times: number; until?: string; daysLeft: number; last: M;
}

/** Calendar day (YYYY-MM-DD) for a timestamp, in `timeZone` (default: this device's). */
export function dayIn(ts: number, timeZone?: string): string {
  const parts = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date(ts));
  const get = (t: string) => parts.find((p) => p.type === t)!.value;
  return `${get('year')}-${get('month')}-${get('day')}`;
}

const between = (a: string, b: string) => Math.round((Date.parse(b + 'T12:00:00Z') - Date.parse(a + 'T12:00:00Z')) / 864e5);

/** Medicine to give today: a daily course still running with doses left today, or a dose whose next-due day has come
    (or passed). The latest entry per medicine name decides. `timeZone`: whose "today" (the server passes the
    person's; the app leaves it out). */
export function medsDue<M extends MedEntry>(items: readonly M[], now = Date.now(), timeZone?: string): MedDue<M>[] {
  const today = dayIn(now, timeZone);
  const meds = items.filter((i) => i.kind === 'med' && !i.deleted).sort((a, b) => a.at - b.at);
  const latest = new Map<string, M>();
  for (const m of meds) latest.set(m.data.name.trim().toLowerCase(), m);
  const out: MedDue<M>[] = [];
  for (const [k, m] of latest) {
    const c = m.data.course;
    if (c && c.times > 0 && dayIn(m.at, timeZone) <= today && today <= c.until) {
      const given = meds.filter((x) => x.data.name.trim().toLowerCase() === k && dayIn(x.at, timeZone) === today).length;
      if (given < c.times) out.push({ key: k, name: m.data.name, what: m.data.what, kind: 'course', given, times: c.times, until: c.until, daysLeft: 0, last: m });
    } else if (!c && m.data.nextDue && m.data.nextDue <= today) {
      out.push({ key: k, name: m.data.name, what: m.data.what, kind: 'due', given: 0, times: 1, daysLeft: between(today, m.data.nextDue), last: m });
    }
  }
  return out.sort((a, b) => a.daysLeft - b.daysLeft || a.name.localeCompare(b.name));
}

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
/** "Nov 25" for 2026-11-25 (no time zone involved: it's already a calendar day). */
export const shortDay = (day: string) => `${MONTHS[Number(day.slice(5, 7)) - 1]} ${Number(day.slice(8, 10))}`;

/** The line under a medicine, the same words as Home's Medicine card. */
export function dueLine(d: MedDue): string {
  if (d.kind === 'course') return `${d.given} of ${d.times} today · until ${shortDay(d.until!)}`;
  return d.daysLeft < 0 ? `Overdue by ${-d.daysLeft} day${d.daysLeft === -1 ? '' : 's'}` : 'Due today';
}
